from content_common import *
import pandas as pd
from prp_data import DATA

def build(b, N):
    b.h1(3, "วิธีวิจัย")
    b.h2("3.1 ขั้นตอนการดำเนินงาน")
    b.p("การประยุกต์ใช้ถ่านชีวภาพทดแทนซีเมนต์ร่วมกับเศษคอนกรีตเหลือทิ้งในการพัฒนาคอนกรีตบล็อกปูพื้นเพื่อความยั่งยืน ดำเนินงานตามขั้นตอนใน{fig:flow} ซึ่งเริ่มจากการทบทวนวรรณกรรมและกำหนดช่องว่างงานวิจัย เตรียมวัสดุ ออกแบบส่วนผสม 2 ชุดการทดลอง ผสมและขึ้นรูปบล็อกด้วยแรงคน บ่มตามอายุ ทดสอบ 4 สมบัติ วิเคราะห์ผลด้วยสถิติและแบบจำลองทางกลศาสตร์ ประเมินคาร์บอนเบื้องต้น และสรุปสูตรที่เหมาะสม")
    b.fig("flow", fp("s_flow_method"), 13.5, "แผนภาพลำดับขั้นตอนการดำเนินงานวิจัย")

    b.h2("3.2 วัสดุในการขึ้นรูปคอนกรีตบล็อกปูพื้น")
    b.p(ot(230, {"ดังแสดงในภาพที่ 3-2": "ดังแสดงใน{fig:materials}"}))
    b.fig("materials", op("materials"), 11.5, "วัสดุหลักที่ใช้ในการขึ้นรูปคอนกรีตบล็อกปูพื้น")
    b.p("เพื่อให้ผู้อ่านประเมินความเหมาะสมของวัสดุและทำซ้ำการทดลองได้ {tab:mats} สรุปสมบัติของวัสดุที่ควรรายงาน ค่าที่ยังไม่มีบันทึกในเอกสารต้นฉบับกำกับด้วย " + PH + " และต้องเติมจากบันทึกการทดสอบวัสดุก่อนเผยแพร่ รายงานนี้ไม่ได้สร้างค่าขึ้นแทน")
    rows = [["ซีเมนต์ปอร์ตแลนด์ประเภท 1", "ตามร่างเดิม", "ยี่ห้อ/รุ่นการผลิต, ความถ่วงจำเพาะ, กำลังอัดมอร์ตาร์ 28 วัน", "<ph>[Place Holder]</ph>"],
            ["ทราย", "ผ่านตะแกรงเบอร์ 4 สภาวะอิ่มตัวผิวแห้ง", "โมดูลัสความละเอียด, ความถ่วงจำเพาะ, การดูดซึมน้ำ", "<ph>[Place Holder]</ph>"],
            ["หินเกล็ด", "ตามร่างเดิม", "ขนาดโตสุด, ความถ่วงจำเพาะ, การดูดซึมน้ำ", "<ph>[Place Holder]</ph>"],
            ["เศษคอนกรีตเหลือทิ้ง (RCA)", "0.30–2.36 มม. (ผ่านเบอร์ 8 ค้างเบอร์ 50) จากห้องปฏิบัติการทดสอบวัสดุ", "กำลังอัดคอนกรีตต้นทาง, ความถ่วงจำเพาะ, การดูดซึมน้ำ, สัดส่วนมอร์ตาร์เดิม, สภาวะความชื้นขณะผสม", "<ph>[Place Holder]</ph>"],
            ["ถ่านชีวภาพจากไม้ไผ่", "ร่อนผ่านตะแกรงเบอร์ 100 และ 200 (150 และ 75 µm)", "อุณหภูมิและเวลาไพโรไลซิส, ปริมาณคาร์บอน, ความหนาแน่นอนุภาค, พื้นที่ผิว, ความอิ่มตัวเริ่มต้น", "<ph>[Place Holder]</ph>"],
            ["น้ำ", "น้ำประปา", "ปริมาณน้ำต่อก้อน (กรัม), อัตราส่วนน้ำต่อวัสดุประสาน", "<ph>[Place Holder]</ph>"]]
    b.table("mats", "วัสดุและสมบัติที่ต้องรายงาน", ["วัสดุ", "การเตรียม", "สมบัติที่ควรรายงาน", "ค่า"], rows, [1900, 2400, 3300, 1050], align=["left", "left", "left", "center"], sz=20)

    b.h2("3.3 การออกแบบอัตราส่วนผสม")
    b.p(ot(234, {"ดังแสดงในตารางที่ 3-1": "ดังแสดงใน{tab:mix}"}).replace("ทดแทนซีเมนต์ในอัตราส่วนประมาณร้อยละ 5 10 15 และ 20 และ ใช้", "ทดแทนซีเมนต์ในอัตราส่วนประมาณร้อยละ 5 10 15 20 และ 25 และใช้"))
    mix = pd.read_csv(os.path.join(DATA, "mix_design_table3-1.csv"))
    rows = []
    for _, r in mix.iterrows():
        pass
    def g(x): return f"{x:,.0f}" if float(x).is_integer() else f"{x:,.2f}"
    rows.append([("__section__", "ส่วนผสมต้นแบบ (ชุดที่ 1)")])
    rows.append(["ส่วนผสมต้นแบบ (RA)", g(600), g(900), g(900), g(900), g(0)])
    rows.append([("__section__", "ชุดที่ 1 : คุมการแทนที่ทรายด้วยเศษคอนกรีตที่ 50% และแทนที่ซีเมนต์ด้วยถ่านชีวภาพ (ไบโอชาร์) ที่ 5–25 เปอร์เซ็นต์")])
    for _, r in mix.iloc[1:6].iterrows(): rows.append([r.mix, g(r.cement_g), g(r.sand_g), g(r.stone_g), g(r.rca_g), g(r.biochar_g)])
    rows.append([("__section__", "ชุดที่ 2 : ไบโอชาร์ 48 กรัมคงที่ และแทนที่ทรายด้วยเศษคอนกรีต 5–15 เปอร์เซ็นต์")])
    for _, r in mix.iloc[6:10].iterrows(): rows.append([r.mix, g(r.cement_g), g(r.sand_g), g(r.stone_g), g(r.rca_g), g(r.biochar_g)])
    b.table("mix", "การออกแบบอัตราส่วนผสมโดยน้ำหนักระหว่างซีเมนต์และไบโอชาร์ ต่อ ทรายและเศษคอนกรีต ต่อหิน 1 : 3 : 1.5 (กรัมต่อก้อน)",
            ["รายละเอียด", "ปูนซีเมนต์", "ทราย", "หิน", "เศษคอนกรีต", "ไบโอชาร์"], rows, [2900, 1150, 1150, 1150, 1150, 1150], align=["left"] + ["center"] * 5,
            note="หมายเหตุ ทุกอัตราส่วนผสมขึ้นรูป 3 ก้อนต่ออายุการทดสอบที่ 7 14 และ 28 วัน ปริมาณน้ำไม่ได้ระบุในตารางต้นฉบับ " + PH + " ส่วนผสมสูตรควบคุมที่ใช้มวลรวมธรรมชาติทั้งหมด (NA) ไม่ปรากฏในตารางต้นฉบับ")
    b.p("เมื่อพิจารณาตัวเลขในตาราง พบว่าฐานของร้อยละในชุดที่ 1 ไม่ใช่การแทนที่ซีเมนต์ด้วยไบโอชาร์ในมวลเท่ากัน ที่ระดับ 5 % ซีเมนต์ลดลง 30 กรัม (ร้อยละ 5 ของ 600 กรัม) แต่ไบโอชาร์ที่เติมคือ 45 กรัม (ร้อยละ 5 ของ 900 กรัม) จึงมีอัตราส่วนไบโอชาร์ต่อซีเมนต์ที่ลดลงเท่ากับ 1.5 ในทุกระดับ {tab:mixderived} แสดงปริมาณที่แท้จริงของแต่ละสูตร ผู้วิจัยใช้ปริมาณซีเมนต์ที่ลดลงเป็นตัวบอกระดับการทดแทนในรายงานนี้ และรายงานปริมาณไบโอชาร์จริงควบคู่ เพื่อให้การเปรียบเทียบกับงานอื่นที่นิยามการทดแทนต่างกันทำได้ถูกต้อง")
    rows = []
    for lab, c, bc, rca in (("Rab5%", 570, 45, 900), ("Rab10%", 540, 90, 900), ("Rab15%", 510, 135, 900), ("Rab20%*", 480, 180, 900), ("Rab25%*", 450, 225, 900)):
        red = 600 - c
        rows.append([lab, f"{red} ({red/600*100:.0f} %)", f"{bc} ({bc/600*100:.1f} %)", f"{bc/red:.2f}", f"{c+bc} ({(c+bc)/600*100:.1f} %)", f"{rca/(900+rca)*100:.0f} %"])
    rows.append(["RCA0–15% (ชุดที่ 2)", "0 (0 %)", "48 (8.0 %)", "—", "648 (108.0 %)", "0–15 % ของทราย"])
    b.table("mixderived", "ปริมาณจริงของซีเมนต์และไบโอชาร์ในแต่ละสูตร (เทียบกับซีเมนต์สูตรควบคุม 600 กรัม)",
            ["สูตร", "ซีเมนต์ที่ลด\n(g, % ของ 600 g)", "ไบโอชาร์ที่เติม\n(g, % ของ 600 g)", "ไบโอชาร์ ÷\nซีเมนต์ที่ลด", "ซีเมนต์ + ไบโอชาร์\n(g, % ของ 600 g)", "RCA ต่อมวลรวม\nละเอียด"],
            rows, [1650, 1500, 1500, 1050, 1700, 1250], align=["left", "center", "center", "center", "center", "center"], sz=20,
            note="หมายเหตุ * สูตรที่ออกแบบแต่ยังไม่มีผลทดสอบ ในชุดที่ 2 ซีเมนต์คงที่ 600 กรัมและไบโอชาร์ 48 กรัมเป็นส่วนเพิ่ม ตามที่ตารางต้นฉบับระบุ ซึ่งขัดกับข้อความในร่างเดิมที่ว่าเป็นการแทนที่ซีเมนต์ร้อยละ 5 จึงต้องยืนยันฐานการคำนวณ " + PH)

    b.h2("3.4 การขึ้นรูปคอนกรีตบล็อกปูพื้น")
    b.h3("3.4.1 เครื่องมือและอุปกรณ์")
    for i in range(240, 246): b.plain(ot(i), left=907, hanging=340, after=40)
    b.plain("", after=40)
    b.fig("mold", op("mold"), 10.5, "แม่พิมพ์คอนกรีตบล็อกปูพื้น")
    b.h3("3.4.2 ขั้นตอนการขึ้นรูปคอนกรีตบล็อกปูพื้น")
    for i in range(249, 257): b.plain(ot(i), left=567, hanging=340, after=40)
    b.plain("", after=40)
    b.fig("forming", op("forming"), 12.5, "การขึ้นรูปคอนกรีตบล็อกปูพื้น")
    b.p("บล็อกแต่ละก้อนอัดด้วยแรงคนและไม้ตำ ซึ่งให้ความหนาแน่นต่ำกว่าและแปรปรวนกว่าการอัดด้วยเครื่อง ผู้วิจัยจึงถือว่าความแตกต่างระหว่างสูตรที่เล็กกว่าความแปรปรวนจากการอัดเป็นความแตกต่างที่ยังสรุปไม่ได้ ดังจะแสดงด้วยการทดสอบทางสถิติในบทที่ 4 ระยะเวลาและเงื่อนไขการบ่มระบุในร่างเดิมว่าตากให้แห้งในอากาศปกติ แต่คำบรรยายภาพที่ 3-7 ระบุว่าบ่มชื้นในอากาศ " + PH + " จึงต้องยืนยันเงื่อนไขการบ่มจริง (อุณหภูมิ ความชื้นสัมพัทธ์ การคลุมชื้น) เพราะส่งผลโดยตรงต่อกำลังที่อายุน้อยและต่อการอธิบายเส้นโค้งการพัฒนากำลัง")

    b.h2("3.5 การดำเนินการทดสอบตามมาตรฐาน")
    b.h3("3.5.1 การทดสอบความหนาแน่น (Density)")
    b.p("ความหนาแน่นคำนวณจากน้ำหนักชิ้นทดสอบต่อปริมาตรตามสมการที่ {eq:dens} ชิ้นทดสอบมีพื้นที่หน้าตัดสุทธิประมาณ 260 ตารางเซนติเมตร และสูง 6 เซนติเมตร คิดเป็นปริมาตร 0.00156 ลูกบาศก์เมตร")
    b.eq("dens", r"D = \frac{W}{V}")
    b.p("โดยที่ D คือ ความหนาแน่นเป็นกิโลกรัมต่อลูกบาศก์เมตร W คือ น้ำหนักตัวอย่างทดสอบเป็นกิโลกรัม และ V คือ ปริมาตรของตัวอย่างทดสอบเป็นลูกบาศก์เมตร")
    b.h3("3.5.2 การทดสอบกำลังต้านทานแรงอัด (Compression Test)")
    b.p(ot(266, {"ดังแสดงในสมการที่ 3-2": "ดังแสดงในสมการที่ {eq:comp}"}) if "ดังแสดงในสมการที่ 3-2" in ot(266) else ot(266).replace("คำนวณความต้านทานแรงอัดดังแสดงในสมการที่ 3-2", "คำนวณความต้านทานแรงอัดดังแสดงในสมการที่ {eq:comp}"))
    b.eq("comp", r"\sigma_{c} = \frac{P}{A}")
    b.p("โดยที่ σ<sub>c</sub> (Compressive Stress) คือ หน่วยแรงอัด หรือ ความต้านทานแรงอัด P คือ ค่ากำลังอัดที่อ่านได้จากเครื่องทดสอบกำลังอัด และ A คือ พื้นที่หน้าตัดที่รับกำลังอัด (หน่วยในงานนี้รายงานเป็น MPa)")
    b.fig("cmmachine", op("cm_machine"), 6.0, "เครื่องทดสอบกำลังอัด")
    b.fig("cmtest", op("cm_test"), 10.0, "ตัวอย่างการทดสอบตัวอย่างด้วยเครื่องทดสอบกำลังอัด (ก) ตัวอย่างทดสอบกำลังอัด (ข) ตัวอย่างที่วิบัติจากการทดสอบ")
    b.h3("3.5.3 การทดสอบการดูดซึมน้ำ (72-hour Water Absorption)")
    b.p(ot(274, {"ดังแสดงในสมการที่ 3-3": "ดังแสดงในสมการที่ {eq:abs}"}) if "ดังแสดงในสมการที่ 3-3" in ot(274) else ot(274).replace("วิธีการคํานวณค่าดูดซึมน้ำดังแสดงในสมการที่ 3-3", "วิธีการคำนวณค่าดูดซึมน้ำดังแสดงในสมการที่ {eq:abs}"))
    b.eq("abs", r"\%W_{t} = \frac{W_{2}-W_{1}}{W_{1}} \times 100")
    b.p("โดยที่ %W<sub>t</sub> คือ ร้อยละการดูดซึมน้ำ W<sub>1</sub> คือ น้ำหนักตัวอย่างทดสอบก่อนแช่น้ำ (กิโลกรัม) และ W<sub>2</sub> คือ น้ำหนักตัวอย่างทดสอบภายหลังแช่น้ำ 72 ชั่วโมงและเช็ดผิวหมาด (กิโลกรัม) ตารางผลในบทที่ 4 ใช้คำว่า “น้ำหนักแห้ง” แทน W<sub>1</sub> ผู้วิจัยยังไม่ได้ระบุว่า W<sub>1</sub> ได้จากการอบแห้งที่ 105 °C จนมวลคงที่หรือการผึ่งอากาศ " + PH + " ซึ่งให้ค่าการดูดซึมต่างกันได้มาก")
    b.p("เครื่องชั่งที่ระบุในรายการอุปกรณ์อ่านละเอียด 0.001 กรัม แต่ค่าน้ำหนักที่บันทึกในตารางผลเป็นกิโลกรัมทศนิยม 2 ตำแหน่ง ซึ่งแสดงว่าอ่านค่าได้ละเอียดเพียง 0.01 กิโลกรัม (10 กรัม) กับก้อนหนักราว 3.3 กิโลกรัม ค่าการดูดซึมน้ำจึงเป็นขั้นละ 0.30 % ดังวิเคราะห์ในหัวข้อ 4.4")
    b.fig("absphoto", op("abs_photos"), 11.5, "ตัวอย่างการทดสอบการแช่น้ำเป็นเวลา 72 ชั่วโมงก่อนชั่งน้ำหนักตัวอย่าง (ก) การบ่มตัวอย่างในอากาศ (ข) การทดสอบการดูดซึมน้ำ (72-hour Water Absorption)")
    b.h3("3.5.4 การทดสอบความต้านทานต่อการลื่นไถล (Skid/Slip Resistance)")
    b.p(ot(281).replace("ซึ่งเป็นอุปกรณ์ที่ได้รับการยอมรับ ในระดับสากล", "ซึ่งเป็นอุปกรณ์ที่ได้รับการยอมรับในระดับสากล"))
    b.p("หลักการของวิธีทดสอบคือปล่อยแขนลูกตุ้มที่ปลายติดสไลเดอร์ยางให้เหวี่ยงผ่านผิวทดสอบ ผิวที่มีแรงเสียดทานสูงทำให้พลังงานสูญเสียมาก แขนเหวี่ยงขึ้นได้ต่ำลง และเข็มอ่านค่า BPN สูงขึ้น ดังแสดงใน{fig:pendulum} ขั้นตอนการทดสอบมีดังนี้")
    b.numbered(["ทำความสะอาดพื้นผิว ประกอบขาตั้ง ปรับระดับฐานด้วยสกรูปรับระดับ และวางเครื่องทดสอบบนตัวอย่าง", "ตั้งค่าศูนย์โดยปล่อยแขนลูกตุ้มเหวี่ยงในแนวดิ่งให้เข็มอ่านค่าหยุดที่เลขศูนย์", "ปรับความสูงเครื่องให้ระยะสัมผัสของสไลเดอร์กับผิวตัวอย่างได้ 12.5 เซนติเมตร (ตามร่างเดิม) วัดอุณหภูมิผิว", "สภาวะแห้ง ปล่อยแขนลูกตุ้มและอ่านค่า ทำซ้ำ 3 ครั้ง บันทึกผล", "สภาวะเปียก พรมน้ำให้เกิดฟิล์มน้ำบาง ๆ ที่แนวสัมผัสใหม่ก่อนทุกสโตรก ยกแขนสู่ตำแหน่งปล่อย ปล่อยให้สไลเดอร์สัมผัสผิวตามระยะ แล้วยกสไลเดอร์ขึ้นขณะดึงแขนกลับเพื่อไม่ให้ครูดผิว", "รายงานค่า BPN เฉลี่ยของแต่ละก้อนทั้งสองสภาวะ"])
    b.fig("pendulum", fp("s_pendulum"), 13.0, "หลักการทำงานและขั้นตอนของเครื่องทดสอบความต้านทานการลื่นไถลแบบลูกตุ้ม (British Pendulum Tester)")
    b.fig("bptphoto", op("bpt_photo"), 8.0, "ตัวอย่างการทดสอบค่าความต้านทานการลื่นไถลโดยใช้เครื่องมือ British Pendulum Tester (BPT)")
    b.p("ร่างเดิมระบุมาตรฐานวิธีทดสอบเป็น ASTM E303-22 {c:astme303} ส่วนค่าอ้างอิงเป็น EN 1338 {c:en1338} ซึ่งใช้ลูกตุ้มเช่นกัน แต่รายละเอียดสไลเดอร์ ระยะสัมผัส และการปรับอุณหภูมิของสองเอกสารไม่ได้เหมือนกันทั้งหมด ผู้วิจัยต้องยืนยันว่าเครื่องที่ใช้ปรับเทียบตามเอกสารใด และยางสไลเดอร์ชนิดใด " + PH)

    b.h2("3.6 การวิเคราะห์ทางสถิติและการควบคุมคุณภาพข้อมูล")
    b.p("ข้อมูลกำลังอัดรายก้อน (n = 3 ต่อสูตรต่ออายุ) วิเคราะห์ด้วยค่าเฉลี่ย ส่วนเบี่ยงเบนมาตรฐานของตัวอย่าง (n − 1) สัมประสิทธิ์การแปรผัน (CV) และช่วงเชื่อมั่นร้อยละ 95 จากการแจกแจงที (t) เปรียบเทียบสูตรด้วยการวิเคราะห์ความแปรปรวนทางเดียว (one-way ANOVA) ภายในแต่ละชุดการทดลองและแต่ละอายุ ตามด้วยการเปรียบเทียบพหุคูณแบบ Tukey HSD ที่ระดับนัยสำคัญ 0.05 และรายงานขนาดผลด้วย η² เนื่องจากแต่ละเซลล์มีเพียง 3 ก้อน กำลังของการทดสอบจึงต่ำ ผลที่ไม่มีนัยสำคัญจึงไม่ได้แปลว่าไม่มีความแตกต่าง")
    b.p("ความสัมพันธ์เชิงกลศาสตร์ใช้การถดถอยเชิงเส้นบนลอการิทึม (สมการที่ {eq:reldens}) และการปรับค่า s ของสมการที่ {eq:maturity} ด้วยกำลังสองน้อยที่สุดจากอัตราส่วนกำลังที่ 7 และ 14 วันต่อ 28 วัน ก่อนวิเคราะห์ได้ตรวจสอบข้อมูล 5 ประการ คือ คำนวณค่าเฉลี่ยซ้ำจากค่ารายก้อน ตรวจความหนาแน่นจากน้ำหนักและปริมาตร ตรวจการดูดซึมน้ำจากน้ำหนักเปียกและแห้ง ตรวจค่าซ้ำที่เหมือนกันทุกค่าระหว่างอายุ และตรวจความละเอียดของเครื่องชั่ง ผลการตรวจทั้งหมดอยู่ในภาคผนวก ข ข้อมูลที่ไม่มีบันทึกต้นฉบับถูกตัดออกจากสถิติทุกรายการ และกำกับด้วย " + PH + " เมื่อแสดงในตาราง การวิเคราะห์ทั้งหมดทำซ้ำได้ด้วยสคริปต์ที่แนบมากับรายงาน")

    b.h2("3.7 การประเมินคาร์บอนเบื้องต้นและต้นทุนวัสดุ")
    b.h3("3.7.1 เป้าหมาย ขอบเขต และหน่วยหน้าที่")
    b.p("เป้าหมายคือเปรียบเทียบ GWP ของสูตรผสมทั้งหมดต่อบล็อกคอนกรีต 1 ลูกบาศก์เมตร (หน่วยหน้าที่ตาม {c:pizon2026}) ขอบเขตแบบ cradle-to-gate รวมการผลิตและจัดหาวัสดุผสม ซึ่งได้แก่ ซีเมนต์ ทราย หินเกล็ด RCA (เฉพาะการบดย่อย) และไบโอชาร์ (กระบวนการไพโรไลซิส) ดังแสดงใน{fig:boundary} ไม่รวมการขนส่ง พลังงานของโรงงาน การใช้งาน และการจัดการเมื่อสิ้นอายุ ซึ่งสอดคล้องกับขอบเขตของ Pizoń และคณะ น้ำไม่นับเพราะมีผลน้อยมาก ในงานของ Pizoń และคณะน้ำคิดเป็นราว 0.2 จาก 440 kg CO<sub>2</sub>e")
    b.fig("boundary", fp("s_system_boundary"), 13.5, "ขอบเขตระบบของการประเมินคาร์บอนเบื้องต้น (cradle-to-gate, A1–A3)")
    b.h3("3.7.2 บัญชีรายการและตัวประกอบการปล่อย")
    b.p("ปริมาณวัสดุต่อลูกบาศก์เมตรคำนวณจากน้ำหนักวัสดุแห้งต่อก้อนในตารางที่ {tab:mix} หารด้วยปริมาตรก้อน 0.00156 ลูกบาศก์เมตร (ข้อมูลที่บันทึกจริง ไม่มีสมมติฐานเพิ่ม) ส่วนตัวประกอบการปล่อยในตารางที่ {tab:ef} เป็นค่าระดับคัดกรอง ตัวประกอบของซีเมนต์อิงค่าของซีเมนต์ไทย {c:khongprom2017} และค่าที่ใช้ในงานของ Wang และคณะ {c:wangd2026} ส่วนตัวประกอบอื่นยังไม่มีแหล่งที่ตรวจสอบได้ในการทบทวนครั้งนี้ จึงเป็นค่าสมมติ " + PH + " ที่ต้องแทนที่ด้วยข้อมูลของ TGO ฐานข้อมูลบัญชีรายการของไทย หรือ ecoinvent ก่อนนำไปอ้างอิง")
    rows = [["ซีเมนต์ปอร์ตแลนด์", "0.76", "0.63 – 0.90", "ค่าฐาน: ซีเมนต์ไทย {c:khongprom2017}; ขอบล่าง: {c:wangd2026}; ขอบบนเป็นสมมติ <ph>[Place Holder]</ph>"],
            ["ทรายธรรมชาติ", "0.004", "0.002 – 0.008", "<ph>[Place Holder]</ph> ค่าสมมติ"],
            ["หินเกล็ด", "0.005", "0.003 – 0.009", "<ph>[Place Holder]</ph> ค่าสมมติ"],
            ["RCA (การบดย่อย)", "0.006", "0.003 – 0.012", "<ph>[Place Holder]</ph> ค่าสมมติ กฎ cut-off"],
            ["ไบโอชาร์ (กระบวนการ)", "0.25", "0.05 – 0.60", "<ph>[Place Holder]</ph> ค่าสมมติ ไม่รวมเครดิตคาร์บอน"],
            ["สัดส่วนคาร์บอนในไบโอชาร์", "0.75", "0.65 – 0.85", "<ph>[Place Holder]</ph> ใช้ในกรณี B"],
            ["ความคงอยู่ของคาร์บอน 100 ปี", "0.80", "0.50 – 0.95", "<ph>[Place Holder]</ph> ใช้ในกรณี B"]]
    b.table("ef", "ตัวประกอบการปล่อยที่ใช้ในการประเมินคาร์บอนเบื้องต้น (kg CO<sub>2</sub>e ต่อ kg วัสดุ ยกเว้นสองแถวสุดท้ายที่เป็นสัดส่วน)", ["วัสดุ/พารามิเตอร์", "ค่าฐาน", "ช่วงที่ใช้ในการจำลอง", "แหล่งและสถานะ"], rows, [2400, 900, 1700, 3650], align=["left", "center", "center", "left"], sz=20)
    b.h3("3.7.3 กรณีวิเคราะห์ ความไม่แน่นอน และตัวชี้วัด")
    b.p("กรณี A ไม่ให้เครดิตคาร์บอนที่กักเก็บในไบโอชาร์ (กรณีฐาน เป็นแนวอนุรักษ์) กรณี B หักเครดิตตามสมการ GWP<sub>B</sub> = GWP<sub>A</sub> − m<sub>biochar</sub> × f<sub>C</sub> × φ × 44/12 โดย f<sub>C</sub> คือสัดส่วนคาร์บอน และ φ คือสัดส่วนที่คงอยู่ตลอด 100 ปี ความไม่แน่นอนประเมินด้วยการจำลองมอนติคาร์โล 20,000 รอบ สุ่มตัวประกอบจากการแจกแจงสามเหลี่ยมตามช่วงในตารางที่ {tab:ef} และใช้ชุดตัวเลขสุ่มชุดเดียวกันกับทุกสูตร (paired) เพื่อให้เทียบสูตรกับสูตรควบคุมได้ตรงจุด รายงานความน่าจะเป็นที่ GWP ของแต่ละสูตรต่ำกว่าสูตรควบคุมของชุดเดียวกัน และวิเคราะห์ความไวทีละตัวแปร (tornado) ตัวชี้วัดเปรียบเทียบมี 3 ตัว คือ GWP ต่อลูกบาศก์เมตร ci ตามสมการที่ {eq:ci} และ bi ตามสมการที่ {eq:bi}")
    b.h3("3.7.4 การคัดกรองต้นทุนวัสดุ")
    b.p("เพื่อตรวจว่าการทดแทนซีเมนต์ด้วยไบโอชาร์คุ้มค่าเชิงต้นทุนหรือไม่ ใช้หน่วยราคาเป็นราคาซีเมนต์ต่อกิโลกรัม (= 1) ร่างเดิมระบุว่าซีเมนต์แพงกว่าทรายประมาณ 10 เท่า จึงกำหนดทรายและหินเท่ากับ 0.1 RCA จากห้องปฏิบัติการถือว่าไม่มีต้นทุน และไบโอชาร์มีราคาเทียบกับซีเมนต์เป็นพารามิเตอร์ r ที่ยังไม่ทราบ " + PH + " ผลที่ได้เป็นดัชนีสัมพัทธ์เทียบกับสูตร RA ไม่ใช่ราคาจริง และมีผลเฉพาะวัสดุ ไม่รวมค่าแรงและพลังงาน")
